2	
3	import com.eaglepoint.storefront.domain.model.FeedType
4	import com.eaglepoint.storefront.domain.model.ParsedFeedItem
5	import org.xml.sax.InputSource
6	import java.io.StringReader
7	import javax.xml.parsers.DocumentBuilderFactory
8	
9	class FeedParser {
10	
11	    fun parse(content: String, feedType: FeedType): List<ParsedFeedItem> {
12	        return when (feedType) {
13	            FeedType.RSS -> parseRss(content)
14	            FeedType.ATOM -> parseAtom(content)
15	            FeedType.HTML_SCRAPE -> emptyList() // HTML scraping requires parseSelector, handled externally
16	        }
17	    }
18	
19	    private fun parseRss(content: String): List<ParsedFeedItem> {
20	        val items = mutableListOf<ParsedFeedItem>()
21	        try {
22	            val factory = DocumentBuilderFactory.newInstance()
23	            factory.isNamespaceAware = false
24	            // Disable external entities for security
25	            factory.setFeature("http://xml.org/sax/features/external-general-entities", false)
26	            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false)
27	            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
28	
29	            val builder = factory.newDocumentBuilder()
30	            val doc = builder.parse(InputSource(StringReader(content)))
31	
32	            val itemNodes = doc.getElementsByTagName("item")
33	            for (i in 0 until itemNodes.length) {
34	                val node = itemNodes.item(i)
35	                val children = node.childNodes
36	
37	                var title = ""
38	                var link = ""
39	                var description: String? = null
40	                var author: String? = null
41	                var pubDate: String? = null
42	
43	                for (j in 0 until children.length) {
44	                    val child = children.item(j)
45	                    when (child.nodeName) {
46	                        "title" -> title = child.textContent?.trim() ?: ""
47	                        "link" -> link = child.textContent?.trim() ?: ""
48	                        "description" -> description = child.textContent?.trim()
49	                        "author", "dc:creator" -> author = child.textContent?.trim()
50	                        "pubDate" -> pubDate = child.textContent?.trim()
51	                    }
52	                }
53	
54	                if (title.isNotBlank() && link.isNotBlank()) {
55	                    items.add(
56	                        ParsedFeedItem(
57	                            title = title,
58	                            summary = description,
59	                            url = link,
60	                            author = author,
61	                            publishedAt = pubDate?.let { parseDate(it) }
62	                        )
63	                    )
64	                }
65	            }
66	        } catch (e: Exception) {
67	            throw FeedParseException("Failed to parse RSS feed: ${e.message}", e)
68	        }
69	        return items
70	    }
71	
72	    private fun parseAtom(content: String): List<ParsedFeedItem> {
73	        val items = mutableListOf<ParsedFeedItem>()
74	        try {
75	            val factory = DocumentBuilderFactory.newInstance()
76	            factory.isNamespaceAware = true
77	            factory.setFeature("http://xml.org/sax/features/external-general-entities", false)
78	            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false)
79	            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
80	
81	            val builder = factory.newDocumentBuilder()
82	            val doc = builder.parse(InputSource(StringReader(content)))
83	
84	            val entryNodes = doc.getElementsByTagName("entry")
85	            for (i in 0 until entryNodes.length) {
86	                val node = entryNodes.item(i)
87	                val children = node.childNodes
88	
89	                var title = ""
90	                var link = ""
91	                var summary: String? = null
92	                var author: String? = null
93	                var updated: String? = null
94	
95	                for (j in 0 until children.length) {
96	                    val child = children.item(j)
97	                    when (child.localName ?: child.nodeName) {
98	                        "title" -> title = child.textContent?.trim() ?: ""
99	                        "link" -> {
100	                            val href = child.attributes?.getNamedItem("href")?.textContent
101	                            if (href != null) link = href.trim()
102	                            else if (link.isBlank()) link = child.textContent?.trim() ?: ""
103	                        }
104	                        "summary", "content" -> {
105	                            if (summary == null) summary = child.textContent?.trim()
106	                        }
107	                        "author" -> {
108	                            val nameNode = child.childNodes
109	                            for (k in 0 until nameNode.length) {
110	                                if ((nameNode.item(k).localName ?: nameNode.item(k).nodeName) == "name") {
111	                                    author = nameNode.item(k).textContent?.trim()
112	                                }
113	                            }
114	                        }
115	                        "updated", "published" -> {
116	                            if (updated == null) updated = child.textContent?.trim()
117	                        }
118	                    }
119	                }
120	
121	                if (title.isNotBlank() && link.isNotBlank()) {
122	                    items.add(
123	                        ParsedFeedItem(
124	                            title = title,
125	                            summary = summary,
126	                            url = link,
127	                            author = author,
128	                            publishedAt = updated?.let { parseDate(it) }
129	                        )
130	                    )
131	                }
132	            }
133	        } catch (e: Exception) {
134	            throw FeedParseException("Failed to parse Atom feed: ${e.message}", e)
135	        }
136	        return items
137	    }
138	
139	    private fun parseDate(dateStr: String): Long? {
140	        return try {
141	            java.text.SimpleDateFormat("EEE, dd MMM yyyy HH:mm:ss Z", java.util.Locale.US)
142	                .parse(dateStr)?.time
143	        } catch (e: Exception) {
144	            try {
145	                java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", java.util.Locale.US)
146	                    .parse(dateStr)?.time
147	            } catch (e2: Exception) {
148	                null
149	            }
150	        }
151	    }
152	}
153	
154	class FeedParseException(message: String, cause: Throwable? = null) : RuntimeException(message, cause)
