3	import android.content.Intent
4	import android.os.Bundle
5	import android.view.View
6	import android.widget.Toast
7	import androidx.appcompat.app.AppCompatActivity
8	import com.eaglepoint.storefront.R
9	import com.eaglepoint.storefront.domain.model.AuthResult
10	import com.eaglepoint.storefront.ui.audit.AuditLogActivity
11	import com.google.android.material.button.MaterialButton
12	import com.google.android.material.textfield.TextInputEditText
13	import com.google.android.material.textfield.TextInputLayout
14	import org.koin.androidx.viewmodel.ext.android.viewModel
15	
16	class LoginActivity : AppCompatActivity() {
17	
18	    private val viewModel: LoginViewModel by viewModel()
19	
20	    private lateinit var usernameLayout: TextInputLayout
21	    private lateinit var usernameInput: TextInputEditText
22	    private lateinit var passwordLayout: TextInputLayout
23	    private lateinit var passwordInput: TextInputEditText
24	    private lateinit var actionButton: MaterialButton
25	    private lateinit var progressBar: View
26	
27	    override fun onCreate(savedInstanceState: Bundle?) {
28	        super.onCreate(savedInstanceState)
29	        setContentView(R.layout.activity_login)
30	
31	        usernameLayout = findViewById(R.id.username_layout)
32	        usernameInput = findViewById(R.id.username_input)
33	        passwordLayout = findViewById(R.id.password_layout)
34	        passwordInput = findViewById(R.id.password_input)
35	        actionButton = findViewById(R.id.action_button)
36	        progressBar = findViewById(R.id.progress_bar)
37	
38	        observeState()
39	        viewModel.checkFirstLaunch()
40	    }
41	
42	    private fun observeState() {
43	        viewModel.isFirstLaunch.observe(this) { isFirst ->
44	            actionButton.text = if (isFirst) {
45	                getString(R.string.create_account)
46	            } else {
47	                getString(R.string.login)
48	            }
49	            actionButton.setOnClickListener {
50	                val username = usernameInput.text?.toString()?.trim() ?: ""
51	                val password = passwordInput.text?.toString()?.toCharArray() ?: charArrayOf()
52	
53	                if (username.isEmpty()) {
54	                    usernameLayout.error = getString(R.string.error_username_required)
55	                    return@setOnClickListener
56	                }
57	                if (password.isEmpty()) {
58	                    passwordLayout.error = getString(R.string.error_password_required)
59	                    return@setOnClickListener
60	                }
61	
62	                usernameLayout.error = null
63	                passwordLayout.error = null
64	
65	                if (isFirst) {
66	                    viewModel.createFirstUser(username, password)
67	                } else {
68	                    viewModel.login(username, password)
69	                }
70	            }
71	        }
72	
73	        viewModel.isLoading.observe(this) { loading ->
74	            progressBar.visibility = if (loading) View.VISIBLE else View.GONE
75	            actionButton.isEnabled = !loading
76	        }
77	
78	        viewModel.loginState.observe(this) { result ->
79	            when (result) {
80	                is AuthResult.Success -> {
81	                    startActivity(Intent(this, AuditLogActivity::class.java))
82	                    finish()
83	                }
84	                is AuthResult.Failure -> {
85	                    passwordLayout.error = result.reason
86	                }
87	                is AuthResult.AccountLocked -> {
88	                    Toast.makeText(this, getString(R.string.account_locked), Toast.LENGTH_LONG).show()
89	                }
90	            }
91	        }
92	    }
93	}
