13	import com.google.android.material.textfield.TextInputLayout
14	import org.koin.androidx.viewmodel.ext.android.viewModel
15	
16	class ReAuthDialogFragment : DialogFragment() {
17	
18	    private val viewModel: ReAuthViewModel by viewModel()
19	
20	    override fun onCreateView(
21	        inflater: LayoutInflater,
22	        container: ViewGroup?,
23	        savedInstanceState: Bundle?
24	    ): View? {
25	        return inflater.inflate(R.layout.dialog_reauth, container, false)
26	    }
27	
28	    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
29	        super.onViewCreated(view, savedInstanceState)
30	
31	        val passwordLayout = view.findViewById<TextInputLayout>(R.id.reauth_password_layout)
32	        val passwordInput = view.findViewById<TextInputEditText>(R.id.reauth_password_input)
33	        val confirmButton = view.findViewById<MaterialButton>(R.id.reauth_confirm_button)
34	        val cancelButton = view.findViewById<MaterialButton>(R.id.reauth_cancel_button)
35	
36	        val userId = arguments?.getString(ARG_USER_ID) ?: run {
37	            dismiss()
38	            return
39	        }
40	
41	        confirmButton.setOnClickListener {
42	            val password = passwordInput.text?.toString()?.toCharArray() ?: charArrayOf()
43	            if (password.isEmpty()) {
44	                passwordLayout.error = getString(R.string.error_password_required)
45	                return@setOnClickListener
46	            }
47	            passwordLayout.error = null
48	            viewModel.reAuthenticate(userId, password)
49	        }
50	
51	        cancelButton.setOnClickListener {
52	            setFragmentResult(REQUEST_KEY, bundleOf(RESULT_AUTHENTICATED to false))
53	            dismiss()
54	        }
55	
56	        viewModel.reAuthResult.observe(viewLifecycleOwner) { success ->
57	            setFragmentResult(REQUEST_KEY, bundleOf(RESULT_AUTHENTICATED to success))
58	            if (!success) {
59	                passwordLayout.error = getString(R.string.error_reauth_failed)
60	            } else {
61	                dismiss()
62	            }
63	        }
64	
65	        viewModel.isLoading.observe(viewLifecycleOwner) { loading ->
66	            confirmButton.isEnabled = !loading
67	        }
68	    }
69	
70	    companion object {
71	        const val REQUEST_KEY = "reauth_request"
72	        const val RESULT_AUTHENTICATED = "authenticated"
73	        private const val ARG_USER_ID = "user_id"
74	
75	        fun newInstance(userId: String): ReAuthDialogFragment {
76	            return ReAuthDialogFragment().apply {
77	                arguments = bundleOf(ARG_USER_ID to userId)
78	            }
79	        }
80	    }
81	}
