1	package com.eaglepoint.storefront.security
2	
3	object SensitiveFieldMasker {
4	
5	    private val SENSITIVE_KEYS = setOf(
6	        "passwordHash",
7	        "passwordSalt",
8	        "password",
9	        "secret",
10	        "token"
11	    )
12	
13	    fun maskHash(hash: ByteArray): String {
14	        if (hash.isEmpty()) return "****"
15	        val prefix = hash.take(2).joinToString("") { "%02x".format(it) }
16	        return "${prefix}..."
17	    }
18	
19	    fun maskId(id: String): String {
20	        if (id.length <= 6) return "****"
21	        return "${id.take(4)}****${id.takeLast(2)}"
22	    }
23	
24	    fun maskForLog(key: String, value: Any?): String {
25	        if (value == null) return "null"
26	        if (isSensitive(key)) return "****"
27	        return value.toString()
28	    }
29	
30	    fun isSensitive(key: String): Boolean {
31	        return SENSITIVE_KEYS.any { key.contains(it, ignoreCase = true) }
32	    }
33	
34	    fun maskDetailMap(details: Map<String, Any?>): Map<String, String> {
35	        return details.mapValues { (key, value) -> maskForLog(key, value) }
36	    }
37	}
