14	class ArticleRepository(
15	    private val articleDao: ArticleDao,
16	    private val dispatcher: CoroutineDispatcher = Dispatchers.IO
17	) {
18	
19	    suspend fun insertAll(articles: List<Article>): Int = withContext(dispatcher) {
20	        val entities = articles.map { domainToEntity(it) }
21	        val results = articleDao.insertAll(entities)
22	        results.count { it != -1L }
23	    }
24	
25	    fun getPage(limit: Int = 50, offset: Int = 0): Flow<List<Article>> {
26	        return articleDao.getPage(limit, offset).map { it.map(::entityToDomain) }
27	    }
28	
29	    fun getBySourceRule(sourceRuleId: String): Flow<List<Article>> {
30	        return articleDao.getBySourceRule(sourceRuleId).map { it.map(::entityToDomain) }
31	    }
32	
33	    suspend fun findById(id: String): Article? = withContext(dispatcher) {
34	        articleDao.findById(id)?.let(::entityToDomain)
35	    }
36	
37	    suspend fun existsByUrl(url: String): Boolean = withContext(dispatcher) {
38	        articleDao.existsByUrl(url)
39	    }
40	
41	    suspend fun countBySourceRule(sourceRuleId: String): Int = withContext(dispatcher) {
42	        articleDao.countBySourceRule(sourceRuleId)
43	    }
44	
45	    fun search(query: ArticleSearchQuery, limit: Int = 50, offset: Int = 0): Flow<List<Article>> {
46	        return articleDao.searchFiltered(
47	            keyword = query.keyword,
48	            sourceRuleId = query.sourceRuleId,
49	            team = query.team,
50	            league = query.league,
51	            dateFrom = query.dateFrom,
52	            dateTo = query.dateTo,
53	            limit = limit,
54	            offset = offset
55	        ).map { it.map(::entityToDomain) }
56	    }
57	
58	    fun searchByKeyword(keyword: String, limit: Int = 50, offset: Int = 0): Flow<List<Article>> {
59	        return articleDao.searchByKeyword(keyword, limit, offset).map { it.map(::entityToDomain) }
60	    }
61	
62	    fun getBySourceAndDateRange(
63	        sourceRuleId: String, dateFrom: Long, dateTo: Long,
64	        limit: Int = 50, offset: Int = 0
65	    ): Flow<List<Article>> {
66	        return articleDao.getBySourceAndDateRange(sourceRuleId, dateFrom, dateTo, limit, offset)
67	            .map { it.map(::entityToDomain) }
68	    }
69	
70	    // Saved / offline
71	    fun getSavedArticles(): Flow<List<Article>> {
72	        return articleDao.getSavedArticles().map { it.map(::entityToDomain) }
73	    }
74	
75	    suspend fun saveForOffline(id: String) = withContext(dispatcher) {
76	        articleDao.saveForOffline(id, System.currentTimeMillis())
77	    }
78	
79	    suspend fun unsaveFromOffline(id: String) = withContext(dispatcher) {
80	        articleDao.unsaveFromOffline(id)
81	    }
82	
83	    fun getSavedCount(): Flow<Int> = articleDao.getSavedCount()
84	
85	    fun getDistinctTeams(): Flow<List<String>> = articleDao.getDistinctTeams()
86	
87	    fun getDistinctLeagues(): Flow<List<String>> = articleDao.getDistinctLeagues()
88	
89	    // Curation
90	    fun getByCurationStatus(status: CurationStatus, limit: Int = 50, offset: Int = 0): Flow<List<Article>> {
91	        return articleDao.getByCurationStatus(status.name, limit, offset).map { it.map(::entityToDomain) }
92	    }
93	
94	    fun getFeatured(): Flow<List<Article>> {
95	        return articleDao.getFeatured().map { it.map(::entityToDomain) }
96	    }
97	
98	    suspend fun updateCurationStatus(id: String, status: CurationStatus, curatedBy: String) =
99	        withContext(dispatcher) {
100	            articleDao.updateCurationStatus(id, status.name, curatedBy, System.currentTimeMillis())
101	        }
102	
103	    suspend fun setFeatured(id: String, featured: Boolean) = withContext(dispatcher) {
104	        articleDao.setFeatured(id, featured, System.currentTimeMillis())
105	    }
106	
107	    suspend fun updateTags(id: String, team: String?, league: String?, topic: String?) =
108	        withContext(dispatcher) {
109	            articleDao.updateTags(id, team, league, topic, System.currentTimeMillis())
110	        }
111	
112	    fun getDistinctTopics(): Flow<List<String>> = articleDao.getDistinctTopics()
113	
114	    fun getPendingReviewCount(): Flow<Int> = articleDao.getPendingReviewCount()
115	
116	    private fun entityToDomain(entity: ArticleEntity): Article {
117	        return Article(
118	            id = entity.id,
119	            sourceRuleId = entity.sourceRuleId,
120	            batchVersionId = entity.batchVersionId,
121	            title = entity.title,
122	            summary = entity.summary,
123	            content = entity.content,
124	            author = entity.author,
125	            externalUrl = entity.externalUrl,
126	            imageUrl = entity.imageUrl,
127	            team = entity.team,
128	            league = entity.league,
129	            isSavedOffline = entity.isSavedOffline,
130	            savedAt = entity.savedAt,
131	            curationStatus = try { CurationStatus.valueOf(entity.curationStatus) } catch (e: Exception) { CurationStatus.PENDING_REVIEW },
132	            curatedBy = entity.curatedBy,
133	            isFeatured = entity.isFeatured,
134	            topic = entity.topic,
135	            publishedAt = entity.publishedAt,
136	            createdAt = entity.createdAt,
137	            updatedAt = entity.updatedAt
138	        )
139	    }
140	
141	    private fun domainToEntity(article: Article): ArticleEntity {
142	        return ArticleEntity(
143	            id = article.id,
144	            sourceRuleId = article.sourceRuleId,
145	            batchVersionId = article.batchVersionId,
146	            title = article.title,
147	            summary = article.summary,
148	            content = article.content,
149	            author = article.author,
150	            externalUrl = article.externalUrl,
151	            imageUrl = article.imageUrl,
152	            team = article.team,
153	            league = article.league,
154	            isSavedOffline = article.isSavedOffline,
155	            savedAt = article.savedAt,
156	            curationStatus = article.curationStatus.name,
157	            curatedBy = article.curatedBy,
158	            isFeatured = article.isFeatured,
159	            topic = article.topic,
160	            publishedAt = article.publishedAt,
161	            createdAt = article.createdAt,
162	            updatedAt = article.updatedAt
163	        )
164	    }
165	}
