1	package com.eaglepoint.storefront.pricing
2	
3	import com.eaglepoint.storefront.data.db.entity.stubs.PriceRuleEntity
4	import com.eaglepoint.storefront.domain.model.Cart
5	import com.eaglepoint.storefront.domain.model.Coupon
6	import com.eaglepoint.storefront.domain.model.PricingResult
7	import kotlin.math.max
8	import kotlin.math.roundToLong
9	
10	class PricingEngine {
11	
12	    fun calculatePrice(
13	        cart: Cart,
14	        priceRules: List<PriceRuleEntity>,
15	        coupon: Coupon?,
16	        taxRate: Double
17	    ): PricingResult {
18	        if (cart.items.isEmpty()) return PricingResult.EMPTY
19	
20	        // 1. Calculate subtotal from line items
21	        val subtotal = cart.items.sumOf { it.lineTotal }
22	
23	        // 2. Apply price rules (sorted by priority DESC)
24	        var ruleDiscount = 0.0
25	        val appliedRules = mutableListOf<String>()
26	
27	        val sortedRules = priceRules.sortedByDescending { it.priority }
28	        for (rule in sortedRules) {
29	            val discount = applyRule(rule, subtotal)
30	            if (discount > 0.0) {
31	                ruleDiscount += discount
32	                appliedRules.add(rule.name)
33	            }
34	        }
35	
36	        // 3. Apply coupon (one coupon max per order)
37	        var couponDiscount = 0.0
38	        var appliedCouponCode: String? = null
39	        if (coupon != null && coupon.isValid) {
40	            val afterRules = subtotal - ruleDiscount
41	            if (afterRules >= coupon.minOrderAmount) {
42	                couponDiscount = when {
43	                    coupon.discountPercent != null -> roundCents(afterRules * coupon.discountPercent / 100.0)
44	                    coupon.discountAmount != null -> minOf(coupon.discountAmount, afterRules)
45	                    else -> 0.0
46	                }
47	                appliedCouponCode = coupon.code
48	            }
49	        }
50	
51	        // 4. Calculate taxable amount and tax
52	        val totalDiscount = ruleDiscount + couponDiscount
53	        val taxableAmount = max(0.0, subtotal - totalDiscount)
54	        val taxAmount = roundCents(taxableAmount * taxRate)
55	
56	        // 5. Final total
57	        val total = roundCents(taxableAmount + taxAmount)
58	
59	        return PricingResult(
60	            subtotal = roundCents(subtotal),
61	            discountAmount = roundCents(ruleDiscount),
62	            couponDiscount = roundCents(couponDiscount),
63	            taxAmount = taxAmount,
64	            taxRate = taxRate,
65	            total = total,
66	            appliedRules = appliedRules,
67	            appliedCoupon = appliedCouponCode
68	        )
69	    }
70	
71	    private fun applyRule(rule: PriceRuleEntity, subtotal: Double): Double {
72	        return when (rule.type) {
73	            RULE_TYPE_PERCENT_OFF -> {
74	                val minAmount = rule.minOrderAmount ?: 0.0
75	                if (subtotal >= minAmount && rule.discountPercent != null) {
76	                    roundCents(subtotal * rule.discountPercent / 100.0)
77	                } else 0.0
78	            }
79	            RULE_TYPE_AMOUNT_OFF -> {
80	                val minAmount = rule.minOrderAmount ?: 0.0
81	                if (subtotal >= minAmount && rule.discountAmount != null) {
82	                    minOf(rule.discountAmount, subtotal)
83	                } else 0.0
84	            }
85	            else -> 0.0
86	        }
87	    }
88	
89	    companion object {
90	        const val RULE_TYPE_PERCENT_OFF = "PERCENT_OFF"
91	        const val RULE_TYPE_AMOUNT_OFF = "AMOUNT_OFF"
92	        const val PRICE_LOCK_DURATION_MS = 30 * 60 * 1000L // 30 minutes
93	
94	        fun roundCents(amount: Double): Double {
95	            return (amount * 100.0).roundToLong() / 100.0
96	        }
97	    }
98	}
