16	
17	class BatchValidationRepository(
18	    private val batchVersionDao: DataBatchVersionDao,
19	    private val validationErrorDao: ValidationErrorDao,
20	    private val dispatcher: CoroutineDispatcher = Dispatchers.IO
21	) {
22	
23	    suspend fun updateBatchValidation(batch: DataBatchVersion) = withContext(dispatcher) {
24	        val entity = batchVersionDao.findById(batch.id)
25	            ?: throw IllegalArgumentException("Batch version not found: ${batch.id}")
26	        batchVersionDao.update(
27	            entity.copy(
28	                errorCount = batch.errorCount,
29	                validationStatus = batch.validationStatus?.name,
30	                errorRate = batch.errorRate,
31	                updatedAt = batch.updatedAt
32	            )
33	        )
34	    }
35	
36	    suspend fun saveValidationErrors(errors: List<ValidationError>) = withContext(dispatcher) {
37	        val entities = errors.map { errorToEntity(it) }
38	        validationErrorDao.insertAll(entities)
39	    }
40	
41	    suspend fun clearErrorsForBatch(batchVersionId: String) = withContext(dispatcher) {
42	        validationErrorDao.deleteByBatchVersion(batchVersionId)
43	    }
44	
45	    fun getErrorsForBatch(batchVersionId: String): Flow<List<ValidationError>> {
46	        return validationErrorDao.getByBatchVersion(batchVersionId).map { entities ->
47	            entities.map { entityToError(it) }
48	        }
49	    }
50	
51	    suspend fun getErrorsForBatchList(batchVersionId: String): List<ValidationError> =
52	        withContext(dispatcher) {
53	            validationErrorDao.getByBatchVersionList(batchVersionId).map { entityToError(it) }
54	        }
55	
56	    suspend fun getErrorCountForBatch(batchVersionId: String): Int = withContext(dispatcher) {
57	        validationErrorDao.countByBatchVersion(batchVersionId)
58	    }
59	
60	    fun getRecentBatches(limit: Int = 50, offset: Int = 0): Flow<List<DataBatchVersion>> {
61	        return batchVersionDao.getRecent(limit, offset).map { entities ->
62	            entities.map { batchEntityToDomain(it) }
63	        }
64	    }
65	
66	    fun getFailedBatches(limit: Int = 20): Flow<List<DataBatchVersion>> {
67	        return batchVersionDao.getRecentFailed(limit).map { entities ->
68	            entities.map { batchEntityToDomain(it) }
69	        }
70	    }
71	
72	    fun getBatchesByStatus(status: BatchValidationStatus): Flow<List<DataBatchVersion>> {
73	        return batchVersionDao.getByValidationStatus(status.name).map { entities ->
74	            entities.map { batchEntityToDomain(it) }
75	        }
76	    }
77	
78	    suspend fun findBatchById(id: String): DataBatchVersion? = withContext(dispatcher) {
79	        batchVersionDao.findById(id)?.let { batchEntityToDomain(it) }
80	    }
81	
82	    private fun batchEntityToDomain(entity: DataBatchVersionEntity): DataBatchVersion {
83	        return DataBatchVersion(
84	            id = entity.id,
85	            batchName = entity.batchName,
86	            version = entity.version,
87	            sourceRuleId = entity.sourceRuleId,
88	            ruleVersion = entity.ruleVersion,
89	            itemsCount = entity.itemsCount,
90	            ingestionJobRunId = entity.ingestionJobRunId,
91	            errorCount = entity.errorCount,
92	            validationStatus = entity.validationStatus?.let {
93	                try { BatchValidationStatus.valueOf(it) } catch (e: Exception) { null }
94	            },
95	            errorRate = entity.errorRate,
96	            createdAt = entity.createdAt,
97	            updatedAt = entity.updatedAt
98	        )
99	    }
100	
101	    private fun errorToEntity(error: ValidationError): ValidationErrorEntity {
102	        return ValidationErrorEntity(
103	            id = error.id,
104	            batchVersionId = error.batchVersionId,
105	            entityType = error.entityType,
106	            entityId = error.entityId,
107	            fieldName = error.fieldName,
108	            ruleName = error.ruleName,
109	            message = error.message,
110	            actualValue = error.actualValue,
111	            severity = error.severity.name,
112	            createdAt = error.createdAt
113	        )
114	    }
115	
116	    private fun entityToError(entity: ValidationErrorEntity): ValidationError {
117	        return ValidationError(
118	            id = entity.id,
119	            batchVersionId = entity.batchVersionId,
120	            entityType = entity.entityType,
121	            entityId = entity.entityId,
122	            fieldName = entity.fieldName,
123	            ruleName = entity.ruleName,
124	            message = entity.message,
125	            actualValue = entity.actualValue,
126	            severity = try { ValidationSeverity.valueOf(entity.severity) } catch (e: Exception) { ValidationSeverity.ERROR },
127	            createdAt = entity.createdAt
128	        )
129	    }
130	}
