    suspend operator fun invoke(
        userId: String,
        action: AuditAction,
        target: String? = null,
        targetId: String? = null,
        detail: String? = null
    ) {
        val event = AuditEvent(
            id = UUID.randomUUID().toString(),
            userId = userId,
            action = action,
            target = target,
            targetId = targetId,
            timestamp = System.currentTimeMillis(),
